{
  "src/vok/rules.ts": "import { Operation, EntityState } from '../types';

export interface VokState extends EntityState {
  entityId: 'vok';
  state: 'nim' | 'dor' | 'mez';
}

export type VokOperation = 
  | { type: 'moveVok'; to: 'nim' | 'dor' | 'mez' }
  | { type: 'fullResetVok' };

export const vokRules = {
  initialState: (): VokState => ({
    entityId: 'vok',
    state: 'nim',
  }),

  applyOperation: (state: VokState, operation: VokOperation): VokState => {
    switch (operation.type) {
      case 'moveVok': {
        return {
          ...state,
          state: operation.to,
        };
      }
      case 'fullResetVok': {
        return {
          ...state,
          state: 'nim',
        };
      }
      default: {
        const _exhaustive: never = operation;
        return _exhaustive;
      }
    }
  },

  isValidTransition: (from: VokState, to: VokState): boolean => {
    // All transitions are valid
    return true;
  },
};
",
  "src/protocol_adapter.ts": "import { VokState, vokRules, VokOperation } from './vok/rules';
import { WorldProtocol } from './types';

type EntityId = 'vok';
type Entity = VokState;
type Operation = VokOperation;

interface WorldState {
  vok: VokState;
}

class ProtocolImpl implements WorldProtocol {
  private state: WorldState;

  constructor() {
    this.state = {
      vok: vokRules.initialState(),
    };
  }

  reset(): void {
    this.state = {
      vok: vokRules.initialState(),
    };
  }

  applyOperation(operation: Operation): void {
    if (operation.type === 'moveVok' || operation.type === 'fullResetVok') {
      this.state.vok = vokRules.applyOperation(this.state.vok, operation);
    }
  }

  getEntityState(entityId: EntityId): Entity | null {
    if (entityId === 'vok') {
      return this.state.vok;
    }
    return null;
  }

  toAbstractSnapshot(): WorldState {
    return {
      vok: {
        entityId: this.state.vok.entityId,
        state: this.state.vok.state,
      },
    };
  }
}

export const protocol: WorldProtocol = new ProtocolImpl();
